use crate::app::*;
use crate::model::{DiffHunk, DiffLine, FileStatus, LineOrigin};
use crate::vcs::traits::VcsType;

struct MockVcs {
    info: VcsInfo,
    /// Total lines available in the "file" (1-indexed)
    total_lines: u32,
}

impl VcsBackend for MockVcs {
    fn info(&self) -> &VcsInfo {
        &self.info
    }

    fn get_working_tree_diff(&self, _highlighter: &SyntaxHighlighter) -> Result<Vec<DiffFile>> {
        Err(TuicrError::NoChanges)
    }

    fn fetch_context_lines(
        &self,
        _file_path: &Path,
        _file_status: FileStatus,
        _ref_commit: Option<&str>,
        start_line: u32,
        end_line: u32,
    ) -> Result<Vec<DiffLine>> {
        let mut result = Vec::new();
        for line_num in start_line..=end_line.min(self.total_lines) {
            result.push(DiffLine {
                origin: LineOrigin::Context,
                content: format!("line {line_num}"),
                old_lineno: Some(line_num),
                new_lineno: Some(line_num),
                highlighted_spans: None,
            });
        }
        Ok(result)
    }

    fn file_line_count(
        &self,
        _file_path: &Path,
        _file_status: FileStatus,
        _ref_commit: Option<&str>,
    ) -> Result<u32> {
        Ok(self.total_lines)
    }
}

fn make_hunk(new_start: u32, new_count: u32) -> DiffHunk {
    let mut lines = Vec::new();
    for i in 0..new_count {
        lines.push(DiffLine {
            origin: LineOrigin::Context,
            content: format!("hunk line {}", new_start + i),
            old_lineno: Some(new_start + i),
            new_lineno: Some(new_start + i),
            highlighted_spans: None,
        });
    }
    DiffHunk {
        header: format!("@@ -{new_start},{new_count} +{new_start},{new_count} @@"),
        lines,
        old_start: new_start,
        old_count: new_count,
        new_start,
        new_count,
    }
}

fn build_app_with_files(files: Vec<DiffFile>, total_lines: u32) -> App {
    let vcs_info = VcsInfo {
        root_path: PathBuf::from("/tmp"),
        head_commit: "abc123".to_string(),
        branch_name: Some("main".to_string()),
        vcs_type: VcsType::Git,
    };
    let session = ReviewSession::new(
        vcs_info.root_path.clone(),
        vcs_info.head_commit.clone(),
        vcs_info.branch_name.clone(),
        SessionDiffSource::WorkingTree,
    );

    App::build(
        Box::new(MockVcs {
            info: vcs_info.clone(),
            total_lines,
        }),
        vcs_info,
        Theme::dark(),
        None,
        false,
        files,
        session,
        DiffSource::WorkingTree,
        InputMode::Normal,
        Vec::new(),
        None,
        None,
    )
    .expect("failed to build test app")
}

fn make_file_with_hunks(path: &str, hunks: Vec<DiffHunk>) -> DiffFile {
    let content_hash = DiffFile::compute_content_hash(&hunks);
    DiffFile {
        old_path: None,
        new_path: Some(PathBuf::from(path)),
        status: FileStatus::Modified,
        hunks,
        is_binary: false,
        is_too_large: false,
        is_commit_message: false,
        content_hash,
    }
}

fn hunk_diff_line(app: &App, file_idx: usize, hunk_idx: usize) -> usize {
    app.line_annotations
        .iter()
        .position(|line| {
            matches!(
                line,
                AnnotatedLine::DiffLine {
                    file_idx: candidate_file_idx,
                    hunk_idx: candidate_hunk_idx,
                    ..
                } if *candidate_file_idx == file_idx && *candidate_hunk_idx == hunk_idx
            )
        })
        .expect("missing hunk diff annotation")
}

#[test]
fn should_cycle_forward_through_review_file_and_line_comments() {
    let file = make_file_with_hunks("test.rs", vec![make_hunk(1, 3)]);
    let mut app = build_app_with_files(vec![file], 20);
    app.diff_state.viewport_height = 4;
    app.session.review_comments.push(Comment::new(
        "review".to_string(),
        CommentType::from_id("note"),
        None,
    ));
    let path = app.diff_files[0].display_path().clone();
    let review = app.session.get_file_mut(&path).unwrap();
    review.add_file_comment(Comment::new(
        "file".to_string(),
        CommentType::from_id("suggestion"),
        None,
    ));
    review.add_line_comment(
        2,
        Comment::new(
            "line".to_string(),
            CommentType::from_id("issue"),
            Some(LineSide::New),
        ),
    );
    app.rebuild_annotations();

    app.diff_state.cursor_line = 0;

    app.next_comment();
    let first_comment = app.diff_state.cursor_line;
    assert!(matches!(
        app.line_annotations.get(app.diff_state.cursor_line),
        Some(AnnotatedLine::ReviewComment { comment_idx: 0 })
    ));

    app.next_comment();
    assert!(matches!(
        app.line_annotations.get(app.diff_state.cursor_line),
        Some(AnnotatedLine::FileComment {
            file_idx: 0,
            comment_idx: 0
        })
    ));

    app.next_comment();
    assert!(matches!(
        app.line_annotations.get(app.diff_state.cursor_line),
        Some(AnnotatedLine::LineComment {
            file_idx: 0,
            line: 2,
            side: LineSide::New,
            comment_idx: 0
        })
    ));

    app.next_comment();
    assert_eq!(app.diff_state.cursor_line, first_comment);
}

#[test]
fn should_cycle_backward_and_skip_current_multiline_comment() {
    let file = make_file_with_hunks("test.rs", vec![make_hunk(1, 3)]);
    let mut app = build_app_with_files(vec![file], 20);
    app.session.review_comments.push(Comment::new(
        "review".to_string(),
        CommentType::from_id("note"),
        None,
    ));
    let path = app.diff_files[0].display_path().clone();
    let review = app.session.get_file_mut(&path).unwrap();
    review.add_file_comment(Comment::new(
        "file\nbody".to_string(),
        CommentType::from_id("suggestion"),
        None,
    ));
    review.add_line_comment(
        2,
        Comment::new(
            "line".to_string(),
            CommentType::from_id("issue"),
            Some(LineSide::New),
        ),
    );
    app.rebuild_annotations();

    let file_comment = app
        .line_annotations
        .iter()
        .position(|line| {
            matches!(
                line,
                AnnotatedLine::FileComment {
                    file_idx: 0,
                    comment_idx: 0
                }
            )
        })
        .expect("missing annotation");
    app.diff_state.cursor_line = file_comment + 2;

    app.prev_comment();

    assert!(matches!(
        app.line_annotations.get(app.diff_state.cursor_line),
        Some(AnnotatedLine::ReviewComment { comment_idx: 0 })
    ));
}

