        let backend = GiteaForgejoBackend::new(ForgeKind::Gitea, None);
        let repo = ForgeRepository::forgejo("http://example.com", "o", "r");
        let err = backend.check_kind(&repo).unwrap_err();
        assert!(matches!(err, TuicrError::Forge(_)));
    }

