    fn should_accept_repository_with_matching_kind() {
        let backend = GiteaForgejoBackend::new(ForgeKind::Forgejo, None);
        let repo = ForgeRepository::forgejo("http://example.com", "o", "r");
        assert!(backend.check_kind(&repo).is_ok());
    }

