    #[test]
    fn should_send_extra_lines_count_anchored_at_start_when_range_supported() {
        let comment = InlineComment {
            path: PathBuf::from("src/lib.rs"),
            line: 20,
            side: GhSide::Left,
            counterpart_line: None,
            start_line: Some(15),
            start_side: Some(GhSide::Left),
            old_path: None,
