    #[serde(default)]
    pub web_url: String,
    #[serde(default)]
    pub state: String,
    #[serde(default)]
    pub draft: bool,
}

impl GlabMrSummary {
    pub fn into_summary(self, repo: &ForgeRepository) -> PullRequestSummary {
        PullRequestSummary {
            repository: repo.clone(),
            number: self.iid,
            title: self.title,
            author: self.author.map(|a| a.username),
            head_ref_name: self.source_branch,
            base_ref_name: self.target_branch,
