    mod lifecycle_tests {
        use super::*;

        #[test]
        fn new_thread_starts_open() {
            let thread = Thread::open(
                Anchor::review(),
                ThreadComment::new(ThreadAuthor::human("alice"), "hi"),
            );
            assert_eq!(thread.status(), ThreadStatus::Open);
            assert!(thread.is_open());
